// Configure these values before activating the workflow.
const CFG = {
  hookSecret: 'REPLACE_WITH_A_LONG_RANDOM_SECRET',
  supabaseUrl: 'https://pfjbbcckedkqbtsykelt.supabase.co',
  whatsappTo: 'REPLACE_WITH_YOUR_PERSONAL_NUMBER_E164',
  whatsappPhoneNumberId: 'REPLACE_WITH_META_PHONE_NUMBER_ID',
};
const root = $input.first()?.json || {};
const headers = root.headers || {};
const supplied = headers['x-was-hook-secret'] || headers['X-WAS-HOOK-SECRET'];
if (!CFG.hookSecret || CFG.hookSecret.startsWith('REPLACE_') || supplied !== CFG.hookSecret) return [];
const event = root.body || root;
if (event.type !== 'INSERT' || event.table !== 'farm_activity') return [];
const record = event.record || {};
const p = record.payload || {};
const allowed = ['operation_created','operation_photos_added','harvest_created','field_report_opened'];
if (!allowed.includes(p.event_kind)) return [];
const lines = ['🌱 WAS الزراعية'];
if (p.event_kind === 'operation_created') {
  lines.push('📝 عملية زراعية جديدة', `الحقل: ${p.field || '—'}`, `العملية: ${p.operation || '—'}`, `التاريخ: ${p.date || '—'}`);
  if (p.fertilizer) lines.push(`السماد: ${p.fertilizer}`, `الجرعة: ${p.dose || '—'}`);\n  if (p.note) lines.push(`ملاحظات: ${p.note}`);
  if (p.cost) lines.push(`التكلفة: ${p.cost}`);
  if (p.photo_count) lines.push(`الصور المرفقة: ${p.photo_count}`);
} else if (p.event_kind === 'operation_photos_added') {
  lines.push('📷 تمت إضافة صور لعملية زراعية', `الحقل: ${p.field || '—'}`, `العملية: ${p.operation || '—'}`, `التاريخ: ${p.date || '—'}`, `عدد الصور: ${(p.photo_paths || []).length || p.photo_count || 0}`);
} else if (p.event_kind === 'harvest_created') {
  lines.push('🚜 تسجيل حصاد جديد', `الحقل: ${p.field || '—'}`, `التاريخ: ${p.date || '—'}`, `الشوالات: ${p.sacks || 0}`, `الصناديق: ${p.crates || 0}`, `الإنتاج: ${p.tons || 0} طن`);
} else if (p.event_kind === 'field_report_opened') {
  lines.push('📄 تقرير حقل', `الحقل: ${p.field || '—'}`, `المساحة: ${p.area || 0} فدان`, `الصنف: ${p.variety || '—'}`, `الإنتاج: ${p.production_tons || 0} طن`, `إنتاجية الفدان: ${Number(p.yield_ton_per_feddan || 0).toFixed(2)} طن`, `العمليات: ${p.operations_count || 0}`, `سجلات الحصاد: ${p.harvest_records || 0}`);
}
const message = lines.join('\n');
const output = [{json:{kind:'text',to:CFG.whatsappTo,phoneNumberId:CFG.whatsappPhoneNumberId,message}}];
for (const path of (p.photo_paths || [])) output.push({json:{kind:'photo',to:CFG.whatsappTo,phoneNumberId:CFG.whatsappPhoneNumberId,path,caption:`📷 WAS الزراعية | ${p.field || 'الحقل'} | ${p.operation || 'صورة مرفقة'}`}});
return output;

const CFG={supabaseUrl:'https://pfjbbcckedkqbtsykelt.supabase.co'};
return $input.all().map((item,index)=>{
  const src=$('Photo or text?').itemMatching(index).json;
  const signed=item.json.signedURL || item.json.signedUrl;
  if(!signed) throw new Error('Supabase did not return a signed photo URL');
  const link=signed.startsWith('http')?signed:CFG.supabaseUrl+'/storage/v1'+(signed.startsWith('/')?signed:'/'+signed);
  return {json:{to:src.to,phoneNumberId:src.phoneNumberId,imageLink:link,caption:src.caption}};
});
